- Amortized analysis based on updated edges and affected nodes
- Memory footprint: O(N+M)

## Code Example
```javascript
// Pseudocode for batch update
function updateBatch(changes) {
  for (const {u,v,w} of changes) {
    if (dist[u] + w < dist[v]) {
      dist[v] = dist[u] + w;
      pq.push(v);
    }
  }
  while (!pq.isEmpty()) {
    const x = pq.pop();
    for (const e of adj[x]) {
      if (dist[x] + e.w < dist[e.v]) {
        dist[e.v] = dist[x] + e.w; pq.push(e.v);
      }
    }
  }
}
